import unittest

from hourglass.rounding import round_labels, round_span
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest(self):
        result = round_span(parse_span("09:07-17:08"), 15)
        self.assertEqual(result, parse_span("09:00-17:15"))

    def test_halfway_rounds_up(self):
        result = round_span(Span(0, 45), 30)
        self.assertEqual(result, Span(0, 60))

    def test_end_of_day_stays(self):
        result = round_span(Span(1400, 1440), 30)
        self.assertEqual(result, Span(1410, 1440))

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 543), 15)

class LabelTests(unittest.TestCase):
    def test_label(self):
        spans = [parse_span("09:02-17:14")]
        labels = round_labels(spans, 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_many_and_empty(self):
        spans = [parse_span("08:00-09:00"), Span(600, 630)]
        self.assertEqual(
            round_labels(spans, 30),
            ["08:00-09:00 (1h 0m)", "10:00-10:30 (0h 30m)"]
        )
        self.assertEqual(round_labels([], 30), [])

    def test_bad_steps(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)
            with self.assertRaises(ValueError):
                round_labels([], step)

if __name__ == "__main__":
    unittest.main()
